const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const hash = (value) => {
  let current = 2166136261;

  for (let index = 0; index < value.length; index++) {
    current ^= value.charCodeAt(index);
    current = Math.imul(current, 16777619);
  }

  return (current >>> 0)
    .toString(16)
    .padStart(8, '0');
};

const gateway_event_type =
  text(input.gateway_event_type || 'inbound_message')
    .toLowerCase();
const clinic_name = text(input.clinic_name);
const client_name = text(input.client_name);
const provider_name = text(input.provider_name);
const channel = text(input.channel).toLowerCase();
const api_key = text(input.api_key);
const signature_verified = bool(input.signature_verified);
const verification_reference =
  text(input.verification_reference);
const source_ip = text(input.source_ip);
const external_event_id =
  text(input.external_event_id);
const external_message_id =
  text(input.external_message_id);
const external_conversation_id =
  text(input.external_conversation_id);
const sender = text(input.sender);
const message_type =
  text(input.message_type || 'text').toLowerCase();
const message_text = text(input.message_text);
const language =
  text(input.language || 'unknown').toLowerCase();
const request_timestamp =
  text(input.request_timestamp) ||
  new Date().toISOString();

const outbound_message_id =
  Number(input.outbound_message_id ?? 0);
const provider_message_id =
  text(input.provider_message_id);
const delivery_event_type =
  text(
    input.delivery_event_type ||
    input.event_type ||
    'unknown'
  ).toLowerCase();
const delivery_event_at =
  text(input.delivery_event_at) ||
  new Date().toISOString();
const error_code = text(input.error_code);
const error_message = text(input.error_message);

const webhook_base_url =
  text(
    input.webhook_base_url ||
    'http://n8n:5678/webhook'
  ).replace(/\/+$/, '');

const confirm_gateway = bool(input.confirm_gateway);

let attachments = input.attachments ?? [];
let raw_payload = input.raw_payload ?? input;
let normalized_payload =
  input.normalized_payload ?? {};

for (const pair of [
  ['attachments', attachments],
  ['raw_payload', raw_payload],
  ['normalized_payload', normalized_payload],
]) {
  if (typeof pair[1] === 'string') {
    try {
      const parsed = JSON.parse(pair[1] || '{}');

      if (pair[0] === 'attachments') {
        attachments = parsed;
      }

      if (pair[0] === 'raw_payload') {
        raw_payload = parsed;
      }

      if (pair[0] === 'normalized_payload') {
        normalized_payload = parsed;
      }
    } catch {
      if (pair[0] === 'attachments') {
        attachments = [];
      }

      if (pair[0] === 'raw_payload') {
        raw_payload = { raw: pair[1] };
      }

      if (pair[0] === 'normalized_payload') {
        normalized_payload = { raw: pair[1] };
      }
    }
  }
}

if (!Array.isArray(attachments)) {
  attachments = [];
}

if (
  !raw_payload ||
  Array.isArray(raw_payload) ||
  typeof raw_payload !== 'object'
) {
  raw_payload = {};
}

if (
  !normalized_payload ||
  Array.isArray(normalized_payload) ||
  typeof normalized_payload !== 'object'
) {
  normalized_payload = {};
}

const request_hash = `gw-${hash(JSON.stringify({
  gateway_event_type,
  clinic_name,
  client_name,
  channel,
  external_event_id,
  external_message_id,
  external_conversation_id,
  sender,
  message_type,
  message_text,
  outbound_message_id,
  provider_message_id,
  delivery_event_type,
  delivery_event_at,
}))}`;

const channels = [
  'whatsapp',
  'sms',
  'phone',
  'telegram',
  'webchat',
  'manual',
  'api',
  'email',
  'web_push',
  'in_app',
];

const messageTypes = [
  'text',
  'audio',
  'image',
  'file',
  'event',
];

const deliveryTypes = [
  'accepted',
  'sent',
  'delivered',
  'read',
  'failed',
  'undeliverable',
  'rejected',
  'unknown',
];

const errors = [];

if (
  !['inbound_message', 'delivery_status'].includes(
    gateway_event_type
  )
) {
  errors.push({
    field: 'gateway_event_type',
    message: 'نوع رویداد Gateway معتبر نیست.',
  });
}

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!client_name) {
  errors.push({
    field: 'client_name',
    message: 'نام Gateway Client الزامی است.',
  });
}

if (!channels.includes(channel)) {
  errors.push({
    field: 'channel',
    message: 'کانال معتبر نیست.',
  });
}

if (!external_event_id) {
  errors.push({
    field: 'external_event_id',
    message: 'شناسه خارجی رویداد الزامی است.',
  });
}

if (Number.isNaN(Date.parse(request_timestamp))) {
  errors.push({
    field: 'request_timestamp',
    message: 'زمان درخواست معتبر نیست.',
  });
}

if (gateway_event_type === 'inbound_message') {
  if (!external_message_id) {
    errors.push({
      field: 'external_message_id',
      message: 'شناسه خارجی پیام الزامی است.',
    });
  }

  if (!external_conversation_id) {
    errors.push({
      field: 'external_conversation_id',
      message: 'شناسه خارجی مکالمه الزامی است.',
    });
  }

  if (!messageTypes.includes(message_type)) {
    errors.push({
      field: 'message_type',
      message: 'نوع پیام معتبر نیست.',
    });
  }

  if (!message_text) {
    errors.push({
      field: 'message_text',
      message: 'متن یا متن استخراج‌شده پیام الزامی است.',
    });
  }
}

if (gateway_event_type === 'delivery_status') {
  if (
    (
      !Number.isInteger(outbound_message_id) ||
      outbound_message_id < 1
    ) &&
    !provider_message_id
  ) {
    errors.push({
      field: 'delivery_reference',
      message: 'شناسه داخلی یا Provider Message ID الزامی است.',
    });
  }

  if (!deliveryTypes.includes(delivery_event_type)) {
    errors.push({
      field: 'delivery_event_type',
      message: 'نوع وضعیت تحویل معتبر نیست.',
    });
  }

  if (Number.isNaN(Date.parse(delivery_event_at))) {
    errors.push({
      field: 'delivery_event_at',
      message: 'زمان وضعیت تحویل معتبر نیست.',
    });
  }
}

if (!/^https?:\/\/.+/i.test(webhook_base_url)) {
  errors.push({
    field: 'webhook_base_url',
    message: 'آدرس Webhook معتبر نیست.',
  });
}

if (confirm_gateway !== true) {
  errors.push({
    field: 'confirm_gateway',
    message: 'پردازش Gateway باید تأیید شود.',
  });
}

return [{
  json: {
    gateway_event_type,
    clinic_name,
    client_name,
    provider_name,
    channel,
    api_key,
    signature_verified,
    verification_reference,
    source_ip,
    external_event_id,
    external_message_id,
    external_conversation_id,
    sender,
    message_type,
    message_text,
    attachments,
    attachments_text:
      JSON.stringify(attachments),
    language,
    request_timestamp,
    outbound_message_id,
    provider_message_id,
    delivery_event_type,
    delivery_event_at,
    error_code,
    error_message,
    normalized_payload,
    normalized_payload_text:
      JSON.stringify(normalized_payload),
    raw_payload,
    raw_payload_text:
      JSON.stringify(raw_payload),
    request_hash,
    webhook_base_url,
    auth_url:
      `${webhook_base_url}/clinic/gateway/security/authenticate`,
    rate_limit_url:
      `${webhook_base_url}/clinic/gateway/security/rate-limit`,
    replay_url:
      `${webhook_base_url}/clinic/gateway/security/replay-check`,
    orchestrator_url:
      `${webhook_base_url}/clinic/conversation/process-message`,
    delivery_url:
      `${webhook_base_url}/clinic/communications/messages/delivery-status`,
    confirm_gateway,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    auth_url: $json.auth_url,
    auth_payload: {
      clinic_name: $json.clinic_name,
      client_name: $json.client_name,
      channel: $json.channel,
      api_key: $json.api_key,
      source_ip: $json.source_ip,
      signature_verified:
        $json.signature_verified,
      verification_reference:
        $json.verification_reference,
      confirm_check: true,
    },
  },
}];

const auth = $json;
const source =
  $('Normalize and Validate Gateway Event')
    .first().json;

return [{
  json: {
    allowed: auth.allowed === true,
    auth_result: auth.result,
    clinic_id: Number(auth.clinic_id || 0),
    client_id: Number(auth.client_id || 0),
    rate_limit_requests:
      Number(auth.rate_limit_requests || 0),
    rate_limit_window_seconds:
      Number(auth.rate_limit_window_seconds || 0),
    replay_window_seconds:
      Number(auth.replay_window_seconds || 0),
    rate_limit_url: source.rate_limit_url,
    rate_limit_payload: {
      client_id: Number(auth.client_id || 0),
      max_requests:
        Number(auth.rate_limit_requests || 0),
      window_seconds:
        Number(auth.rate_limit_window_seconds || 0),
      confirm_check: true,
    },
  },
}];

const rate = $json;
const auth =
  $('Prepare Rate Limit Request')
    .first().json;
const source =
  $('Normalize and Validate Gateway Event')
    .first().json;

return [{
  json: {
    allowed: rate.allowed === true,
    rate_limit_result: rate.result,
    retry_after_seconds:
      Number(rate.retry_after_seconds || 0),
    remaining_requests:
      Number(rate.remaining_requests || 0),
    replay_url: source.replay_url,
    replay_payload: {
      clinic_id: auth.clinic_id,
      client_id: auth.client_id,
      gateway_event_type:
        source.gateway_event_type,
      channel: source.channel,
      external_event_id:
        source.external_event_id,
      external_message_id:
        source.external_message_id,
      request_hash: source.request_hash,
      source_ip: source.source_ip,
      request_timestamp:
        source.request_timestamp,
      replay_window_seconds:
        auth.replay_window_seconds,
      confirm_check: true,
    },
  },
}];

const source =
  $('Normalize and Validate Gateway Event')
    .first().json;
const auth =
  $('Prepare Rate Limit Request')
    .first().json;
const replay =
  $('Check Replay and Duplicate Event')
    .first().json;

return [{
  json: {
    inbound_channel_message_id:
      Number($json.inbound_channel_message_id),
    gateway_request_id:
      Number(replay.gateway_request_id),
    orchestrator_url:
      source.orchestrator_url,
    orchestrator_payload: {
      clinic_name: source.clinic_name,
      channel: source.channel,
      external_conversation_id:
        source.external_conversation_id,
      mobile: source.sender,
      message_type: source.message_type,
      message_text: source.message_text,
      message_payload: {
        gateway_request_id:
          Number(replay.gateway_request_id),
        inbound_channel_message_id:
          Number($json.inbound_channel_message_id),
        client_id: auth.client_id,
        client_name: source.client_name,
        provider_name: source.provider_name,
        external_event_id:
          source.external_event_id,
        external_message_id:
          source.external_message_id,
        attachments: source.attachments,
        normalized_payload:
          source.normalized_payload,
      },
      language: source.language,
      webhook_base_url:
        source.webhook_base_url,
      confirm_message: true,
    },
  },
}];

const source =
  $('Normalize and Validate Gateway Event')
    .first().json;
const replay =
  $('Check Replay and Duplicate Event')
    .first().json;

return [{
  json: {
    provider_callback_event_id:
      Number($json.provider_callback_event_id),
    gateway_request_id:
      Number(replay.gateway_request_id),
    delivery_url:
      source.delivery_url,
    delivery_payload: {
      outbound_message_id:
        source.outbound_message_id,
      provider_message_id:
        source.provider_message_id,
      channel: source.channel,
      event_type:
        source.delivery_event_type,
      event_at:
        source.delivery_event_at,
      error_code:
        source.error_code,
      error_message:
        source.error_message,
      raw_event:
        source.raw_payload,
    },
  },
}];
